using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses();
    List<Course> GetFeaturedCourses();
    List<Course> GetCoursesByDepartment(int departmentId);
    List<Course> SearchCourses(string? searchTerm, int? departmentId);
    Course? GetCourse(int id);
    Instructor? GetInstructor(int id);
}

public class CatalogService : ICatalogService
{
    private readonly List<Instructor> _instructors;
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 peer-reviewed papers and holds three patents in neural network optimization.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Rodriguez", Title = "Associate Professor of Mathematics", Bio = "Dr. Rodriguez earned his PhD from MIT and has been teaching calculus and linear algebra for over 15 years. He is known for making complex mathematical concepts accessible to all students.", Email = "j.rodriguez@university.edu" },
            new() { Id = 3, Name = "Prof. Emily Watson", Title = "Professor of English Literature", Bio = "Prof. Watson is an award-winning author and literary critic. Her research focuses on post-colonial literature and contemporary American fiction.", Email = "e.watson@university.edu" },
            new() { Id = 4, Name = "Dr. Michael Park", Title = "Associate Professor of Physics", Bio = "Dr. Park's research in quantum mechanics has been recognized with multiple national awards. He leads the university's quantum computing research lab.", Email = "m.park@university.edu" },
            new() { Id = 5, Name = "Dr. Lisa Thompson", Title = "Professor of History", Bio = "Dr. Thompson is a specialist in medieval European history. She has led archaeological expeditions across Europe and authored several acclaimed history textbooks.", Email = "l.thompson@university.edu" },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Assistant Professor of Computer Science", Bio = "Dr. Kim focuses on cybersecurity and distributed systems. Before joining academia, he spent 10 years in the software industry working on large-scale cloud platforms.", Email = "d.kim@university.edu" },
            new() { Id = 7, Name = "Dr. Anna Müller", Title = "Professor of Biology", Bio = "Dr. Müller leads the molecular biology lab and has contributed to breakthrough research in gene therapy. She mentors graduate students in bioinformatics and genomics.", Email = "a.muller@university.edu" },
            new() { Id = 8, Name = "Prof. Robert Garcia", Title = "Associate Professor of Philosophy", Bio = "Prof. Garcia explores ethics in technology and has published extensively on the philosophy of artificial intelligence and digital rights.", Email = "r.garcia@university.edu" },
        };

        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Explore computing theory, software engineering, artificial intelligence, and data science." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study pure and applied mathematics including calculus, algebra, statistics, and analysis." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Develop critical reading, writing, and analytical skills through the study of literature and rhetoric." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Investigate the fundamental laws of nature from classical mechanics to quantum physics." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Examine the past to understand how events, ideas, and cultures have shaped the modern world." },
            new() { Id = 6, Name = "Biology", Code = "BIO", Description = "Study living organisms, from molecular genetics to ecology and evolutionary biology." },
            new() { Id = 7, Name = "Philosophy", Code = "PHIL", Description = "Engage with fundamental questions about knowledge, existence, ethics, and reasoning." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and object-oriented programming. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Tech Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study essential data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Prerequisites: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", Location = "Tech Hall 305", DepartmentId = 1, InstructorId = 1, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 310", Title = "Cybersecurity Fundamentals", Description = "An introduction to cybersecurity principles including threat modeling, cryptography, network security, and ethical hacking. Hands-on labs included.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Location = "Tech Hall 110", DepartmentId = 1, InstructorId = 6, IsFeatured = true, MaxEnrollment = 40, CurrentEnrollment = 38 },

            // Mathematics
            new() { Id = 4, Code = "MATH 151", Title = "Calculus I", Description = "A first course in differential and integral calculus. Topics include limits, derivatives, integrals, and the Fundamental Theorem of Calculus. Applications to science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Science Center 101", DepartmentId = 2, InstructorId = 2, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 5, Code = "MATH 220", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to computer graphics and data analysis.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Location = "Science Center 203", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },

