            new() { Id = 6, Code = "ENG 101", Title = "College Composition", Description = "Develop essential academic writing skills through reading, analysis, and composition. Focus on thesis development, argumentation, and research methods.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities 301", DepartmentId = 3, InstructorId = 3, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 7, Code = "ENG 250", Title = "American Literature Survey", Description = "A survey of American literature from the colonial period to the present. Readings include works by Hawthorne, Twain, Fitzgerald, Morrison, and contemporary authors.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Location = "Humanities 205", DepartmentId = 3, InstructorId = 3, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 22 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Introduction to mechanics, thermodynamics, and waves. Includes weekly lab sessions. Corequisite: MATH 151.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM, Lab: Fri 2:00–4:50 PM", Location = "Physics Building 100", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 78 },
            new() { Id = 9, Code = "PHYS 330", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, measurement, and applications to atomic and molecular systems.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", Location = "Physics Building 210", DepartmentId = 4, InstructorId = 4, IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 24 },

