            new() { Id = 12, Code = "BIO 101", Title = "Introduction to Biology", Description = "Fundamentals of cell biology, genetics, evolution, and ecology. Lab sessions include microscopy, DNA extraction, and ecological surveys.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM, Lab: Wed 1:00–3:50 PM", Location = "Life Sciences 100", DepartmentId = 6, InstructorId = 7, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 88 },
            new() { Id = 13, Code = "BIO 340", Title = "Molecular Biology", Description = "Study of molecular mechanisms of gene expression, DNA replication, transcription, translation, and regulation. Includes hands-on laboratory work with modern techniques.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM, Lab: Thu 1:00–3:50 PM", Location = "Life Sciences 220", DepartmentId = 6, InstructorId = 7, IsFeatured = true, MaxEnrollment = 24, CurrentEnrollment = 20 },

