            new() { Id = 14, Code = "PHIL 101", Title = "Introduction to Philosophy", Description = "An introduction to major philosophical questions and traditions. Topics include the nature of knowledge, free will, ethics, and the existence of God.", Credits = 3, Schedule = "Mon/Wed 3:00–4:15 PM", Location = "Humanities 102", DepartmentId = 7, InstructorId = 8, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },
            new() { Id = 15, Code = "PHIL 275", Title = "Ethics in Technology", Description = "Examine ethical issues arising from modern technology: AI bias, data privacy, autonomous systems, social media, and digital rights. Case studies and debates.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", Location = "Humanities 102", DepartmentId = 7, InstructorId = 8, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);
}

