        <h2 class="mb-3">Departments</h2>
        <div class="row g-3">
            @foreach (var dept in departments)
            {
                var courseCount = Catalog.GetCoursesByDepartment(dept.Id).Count;
                <div class="col-md-6 col-lg-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name <span class="text-muted">(@dept.Code)</span></h5>
