@page "/catalog"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService Catalog
@rendermode InteractiveServer

<PageTitle>Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Course Catalog</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search courses by title, code, or keyword…"
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="selectedDepartmentId">
                <option value="0">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id">@dept.Name (@dept.Code)</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
        </div>
    </div>

    @if (filteredCourses.Count == 0)
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
    else
    {
        <p class="text-muted mb-3">Showing @filteredCourses.Count course@(filteredCourses.Count != 1 ? "s" : "")</p>

        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Schedule</th>
                        <th>Availability</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in filteredCourses)
                    {
                        var dept = Catalog.GetDepartment(course.DepartmentId);
                        var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                        <tr>
                            <td><strong>@course.Code</strong></td>
                            <td>@course.Title</td>
                            <td>@dept?.Name</td>
                            <td>@course.Credits</td>
                            <td class="small">@course.Schedule</td>
                            <td>
                                @if (spotsLeft <= 0)
                                {
                                    <span class="badge bg-danger">Full</span>
                                }
                                else if (spotsLeft <= 5)
                                {
                                    <span class="badge bg-warning text-dark">@spotsLeft spots left</span>
                                }
                                else
                                {
                                    <span class="badge bg-success">@spotsLeft spots left</span>
                                }
                            </td>
                            <td><a href="/course/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
