            <hr />
            <a href="/catalog" class="btn btn-outline-success">Browse More Courses</a>
        </div>
    }
    else
    {
        <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields marked with * are required.</p>

        <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
            <DataAnnotationsValidator />
            <AntiforgeryToken />

            <div class="row">
                <div class="col-md-8">
                    <div class="mb-3">
                        <label for="name" class="form-label">Full Name *</label>
                        <InputText id="name" class="form-control" @bind-Value="Model.Name" />
                        <ValidationMessage For="() => Model.Name" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID *</label>
                        <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g. STU123456" />
                        <ValidationMessage For="() => Model.StudentId" />
                    </div>

                    <div class="mb-3">
                        <label for="email" class="form-label">Email Address</label>
                        <InputText id="email" class="form-control" @bind-Value="Model.Email" type="email" />
                        <ValidationMessage For="() => Model.Email" />
                    </div>

                    <div class="mb-3">
                        <label for="course" class="form-label">Course *</label>
                        <InputSelect id="course" class="form-select" @bind-Value="Model.CourseId">
                            <option value="0">— Select a course —</option>
                            @foreach (var course in courses)
                            {
                                var dept = Catalog.GetDepartment(course.DepartmentId);
                                var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                                <option value="@course.Id" disabled="@(spotsLeft <= 0)">
                                    @course.Code — @course.Title (@(spotsLeft > 0 ? $"{spotsLeft} spots left" : "Full"))
                                </option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                </div>
            </div>
        </EditForm>
