@page "/course/{Id:int}"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found") — Course Catalog</PageTitle>

<div class="container py-4">
    @if (course is null)
    {
        <div class="alert alert-warning">
            <h4>Course Not Found</h4>
            <p>The requested course could not be found. <a href="/catalog">Return to catalog</a>.</p>
        </div>
    }
    else
    {
        var dept = Catalog.GetDepartment(course.DepartmentId);
        var instructor = Catalog.GetInstructor(course.InstructorId);
        var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;

        <nav aria-label="breadcrumb" class="mb-3">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/catalog?departmentId=@course.DepartmentId">@dept?.Name</a></li>
                <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
            </ol>
        </nav>

        <div class="row">
            <div class="col-lg-8">
                <h1>@course.Code — @course.Title</h1>
                <span class="badge bg-secondary me-2">@dept?.Name</span>
                <span class="badge bg-info text-dark">@course.Credits Credits</span>
                @if (spotsLeft <= 0)
                {
                    <span class="badge bg-danger ms-2">Full</span>
                }
                else if (spotsLeft <= 5)
                {
                    <span class="badge bg-warning text-dark ms-2">@spotsLeft spots left</span>
                }

                <hr />

                <h4>Description</h4>
                <p>@course.Description</p>

                <h4>Schedule &amp; Location</h4>
                <dl class="row">
                    <dt class="col-sm-3">Schedule</dt>
                    <dd class="col-sm-9">@course.Schedule</dd>

                    <dt class="col-sm-3">Location</dt>
                    <dd class="col-sm-9">@course.Location</dd>

                    <dt class="col-sm-3">Enrollment</dt>
                    <dd class="col-sm-9">@course.CurrentEnrollment / @course.MaxEnrollment students</dd>
                </dl>

                @if (spotsLeft > 0)
                {
                    <a href="/enroll?courseId=@course.Id" class="btn btn-primary">Enroll in This Course</a>
                }
            </div>

            <div class="col-lg-4">
                @if (instructor is not null)
                {
                    <div class="card">
                        <div class="card-body">
                            <h5 class="card-title">Instructor</h5>
                            <h6>@instructor.Name</h6>
                            <p class="text-muted mb-2">@instructor.Title</p>
                            <p class="small">@instructor.Bio</p>
                            <a href="mailto:@instructor.Email" class="text-decoration-none">@instructor.Email</a>
                        </div>
                    </div>
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

